CREATE OR REPLACE FUNCTION private.validate_mission_shortlist_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  mission_workspace uuid;
  creator_workspace uuid;
begin
  select workspace_id into mission_workspace
  from public.missions
  where id = new.mission_id;

  select workspace_id into creator_workspace
  from public.creators
  where id = new.creator_id;

  if mission_workspace is null or creator_workspace is null then
    return new;
  end if;

  if mission_workspace <> creator_workspace or new.workspace_id <> mission_workspace then
    raise exception 'mission_shortlists workspace mismatch'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_application(p_submission uuid)
 RETURNS mission_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sub public.mission_submissions;
  v_rows int;
begin
  select * into v_sub from public.mission_submissions where id = p_submission for update;
  if v_sub.id is null then raise exception 'not_found'; end if;
  if v_sub.status = 'joined' then return v_sub; end if;                       -- idempotent
  if v_sub.status <> 'applied' then raise exception 'wrong_state'; end if;

  update public.missions set filled = filled + 1
    where id = v_sub.mission_id and filled < quota;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then raise exception 'mission_full'; end if;

  update public.mission_submissions set
    status = 'joined', xp_awarded = xp_awarded + 10
    where id = p_submission
    returning * into v_sub;
  update public.creators set xp = xp + 10 where id = v_sub.creator_id;
  return v_sub;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_mission(p_mission uuid)
 RETURNS mission_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator uuid := auth.uid();
  v_ws uuid;
  m record;
  v_sub public.mission_submissions;
begin
  if v_creator is null then raise exception 'not_authenticated'; end if;

  select workspace_id into v_ws from public.creators where id = v_creator;
  if v_ws is null then raise exception 'not_found'; end if;

  select id, workspace_id, status, access_type, deadline
    into m from public.missions where id = p_mission;
  if m.id is null or m.workspace_id <> v_ws then raise exception 'not_found'; end if;
  if m.status <> 'active' then raise exception 'closed'; end if;
  if m.access_type <> 'application' then raise exception 'not_application'; end if;
  if m.deadline is not null and m.deadline < current_date then raise exception 'closed'; end if;

  -- unique(mission_id, creator_id) is the real dedupe guard (handles a double-tap race).
  begin
    insert into public.mission_submissions
      (mission_id, creator_id, workspace_id, status, xp_awarded)
      values (p_mission, v_creator, v_ws, 'applied', 0)
      returning * into v_sub;
  exception when unique_violation then
    raise exception 'already_applied';
  end;
  return v_sub;
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_submission(p_submission uuid, p_notes text, p_quality_rating smallint DEFAULT NULL::smallint)
 RETURNS mission_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sub public.mission_submissions;
  v_points int;
  v_title text;
  v_cash numeric;
  v_bal int;
  v_earn_bal numeric;
  v_bonus int := 0;
  v_bgt_bal numeric;
  v_bgt_enforced boolean;
begin
  if p_quality_rating is not null and (p_quality_rating < 1 or p_quality_rating > 5)
    then raise exception 'bad_rating'; end if;

  select * into v_sub from public.mission_submissions where id = p_submission for update;
  if v_sub.id is null then raise exception 'not_found'; end if;
  if v_sub.status = 'approved' then return v_sub; end if;                         -- idempotent
  if v_sub.status not in ('submitted','under_review') then raise exception 'wrong_state'; end if;

  select points_reward, title, cash_reward into v_points, v_title, v_cash
    from public.missions where id = v_sub.mission_id;

  -- Slice 3: brand budget hard cap. When the workspace has enforcement ON, the cash payout
  -- must fit the wallet; debit it (a raise here rolls back the whole transaction → nothing paid).
  if coalesce(v_cash, 0) > 0 then
    select balance, enforced into v_bgt_bal, v_bgt_enforced
      from public.workspace_budgets where workspace_id = v_sub.workspace_id for update;
    if v_bgt_enforced is true then
      if v_bgt_bal < v_cash then raise exception 'insufficient_budget'; end if;
      update public.workspace_budgets set balance = balance - v_cash, updated_at = now()
        where workspace_id = v_sub.workspace_id;
      insert into public.workspace_budget_transactions
        (workspace_id, type, delta, balance_after, source_ref, description)
        values (v_sub.workspace_id, 'debit', -v_cash, v_bgt_bal - v_cash,
                'mission_submission:' || p_submission, v_title);
    end if;
  end if;

  -- Points award (unchanged from Slice 4).
  update public.point_balances set balance = balance + v_points, updated_at = now()
    where creator_id = v_sub.creator_id and workspace_id = v_sub.workspace_id
    returning balance into v_bal;
  if v_bal is null then
    raise exception 'point_balances row missing for creator %', v_sub.creator_id;
  end if;
  insert into public.point_transactions
    (creator_id, workspace_id, type, delta, balance_after, source_ref, description)
    values (v_sub.creator_id, v_sub.workspace_id, 'earn', v_points, v_bal,
            'mission_submission:' || p_submission, v_title);

  -- Cash accrual (unchanged from Slice 5).
  if coalesce(v_cash, 0) > 0 then
    update public.earnings_balances set available = available + v_cash, updated_at = now()
      where creator_id = v_sub.creator_id and workspace_id = v_sub.workspace_id
      returning available into v_earn_bal;
    if v_earn_bal is null then
      raise exception 'earnings_balances row missing for creator %', v_sub.creator_id;
    end if;
    insert into public.earnings_transactions
      (creator_id, workspace_id, type, amount, balance_after, source_ref, description)
      values (v_sub.creator_id, v_sub.workspace_id, 'earn', v_cash, v_earn_bal,
              'mission_submission:' || p_submission, v_title);
  end if;

  -- Slice 6C: a perfect 5-star rating earns +50 bonus XP (master-spec 7.2).
  if p_quality_rating = 5 then v_bonus := 50; end if;

  update public.mission_submissions set
    status = 'approved', reviewed_at = now(), reviewer_notes = p_notes,
    quality_rating = p_quality_rating,
    points_awarded = v_points, xp_awarded = xp_awarded + 100 + v_bonus
    where id = p_submission
    returning * into v_sub;
  update public.creators set xp = xp + 100 + v_bonus where id = v_sub.creator_id;
  return v_sub;
end;
$function$

CREATE OR REPLACE FUNCTION public.award_welcome_bonus(p_creator uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ws   uuid;
  v_done boolean;
  v_bal  integer;
begin
  select workspace_id, onboarding_completed
    into v_ws, v_done
    from public.creators
    where id = p_creator
    for update;

  if v_ws is null then
    raise exception 'creator % not found', p_creator;
  end if;
  if v_done then
    return;  -- already onboarded → no double award
  end if;

  update public.point_balances
    set balance = balance + 100, updated_at = now()
    where creator_id = p_creator and workspace_id = v_ws
    returning balance into v_bal;

  if v_bal is null then
    -- bootstrap always seeds a balance row; a missing one is an invariant breach.
    -- Fail loudly (leaving onboarding_completed=false for retry) rather than
    -- recording a NULL balance_after and locking the creator out of the award.
    raise exception 'point_balances row missing for creator %', p_creator;
  end if;

  insert into public.point_transactions
    (creator_id, workspace_id, type, delta, balance_after, source_ref, description)
    values (p_creator, v_ws, 'bonus', 100, v_bal, 'welcome', '迎新獎賞 100 積分');

  update public.creators
    set onboarding_completed = true, onboarding_step = 5
    where id = p_creator;
end;
$function$

CREATE OR REPLACE FUNCTION public.campaign_progress_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_c    record;
  v_part public.campaign_participants;
begin
  -- Only the transition into 'approved' (monotonic; approved is terminal).
  if not (old.status is distinct from 'approved' and new.status = 'approved') then
    return new;
  end if;

  -- The single live campaign whose ACTIVE set contains this mission (one-active-per-mission).
  select c.id, c.workspace_id, c.starts_at, c.ends_at, c.goal_target
    into v_c
    from public.campaign_missions cm
    join public.campaigns c on c.id = cm.campaign_id and c.workspace_id = cm.workspace_id
   where cm.mission_id = new.mission_id
     and cm.removed_at is null
     and c.status <> 'settled'
   for share of c;                              -- fences against close_campaign's for update
  if v_c.id is null then return new; end if;

  -- Window eligibility keys on submitted_at (delivered-in-window), not reviewed_at/now().
  if not (new.submitted_at >= v_c.starts_at and new.submitted_at < v_c.ends_at) then
    return new;
  end if;

  -- Auto-enroll, then lock the participant row and count from the LOCKED row (never a recount).
  insert into public.campaign_participants (campaign_id, creator_id, workspace_id, approved_count)
    values (v_c.id, new.creator_id, v_c.workspace_id, 0)
    on conflict (campaign_id, creator_id) do nothing;
  select * into v_part from public.campaign_participants
    where campaign_id = v_c.id and creator_id = new.creator_id for update;

  update public.campaign_participants
     set approved_count    = approved_count + 1,
         last_approved_at   = now(),
         first_approved_at  = coalesce(first_approved_at, now())
   where id = v_part.id
   returning * into v_part;

  if v_part.approved_count >= v_c.goal_target and v_part.goal_reached_at is null then
    update public.campaign_participants set goal_reached_at = now() where id = v_part.id;
    perform public.grant_campaign_completion_bonus(v_c.id, new.creator_id);
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.close_campaign(p_campaign uuid)
 RETURNS campaigns
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_c public.campaigns;
begin
  select * into v_c from public.campaigns where id = p_campaign for update;
  if v_c.id is null then raise exception 'not_found'; end if;
  if v_c.status <> 'active' then raise exception 'wrong_state'; end if;
  update public.campaigns set status = 'closed', closed_at = now(), updated_at = now()
    where id = p_campaign returning * into v_c;
  return v_c;
end;
$function$

CREATE OR REPLACE FUNCTION public.credit_workspace_budget(p_workspace uuid, p_delta numeric, p_type text, p_description text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_bal numeric;
begin
  if p_type not in ('topup','adjust') then raise exception 'bad_type'; end if;
  insert into public.workspace_budgets (workspace_id) values (p_workspace)
    on conflict (workspace_id) do nothing;
  select balance into v_bal from public.workspace_budgets
    where workspace_id = p_workspace for update;
  if v_bal + p_delta < 0 then raise exception 'negative_balance'; end if;
  update public.workspace_budgets set balance = balance + p_delta, updated_at = now()
    where workspace_id = p_workspace returning balance into v_bal;
  insert into public.workspace_budget_transactions
    (workspace_id, type, delta, balance_after, description)
    values (p_workspace, p_type, p_delta, v_bal, p_description);
  return v_bal;
end;
$function$

CREATE OR REPLACE FUNCTION public.decline_application(p_submission uuid, p_notes text)
 RETURNS mission_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sub public.mission_submissions;
begin
  select * into v_sub from public.mission_submissions where id = p_submission for update;
  if v_sub.id is null then raise exception 'not_found'; end if;
  if v_sub.status = 'declined' then return v_sub; end if;                     -- idempotent
  if v_sub.status <> 'applied' then raise exception 'wrong_state'; end if;

  update public.mission_submissions set
    status = 'declined', reviewer_notes = p_notes, reviewed_at = now()
    where id = p_submission
    returning * into v_sub;
  return v_sub;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_campaign_completion_bonus(p_campaign uuid, p_creator uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_part   public.campaign_participants;
  v_ws     uuid;
  v_points int;
  v_xp     int;
  v_status text;
  v_title  text;
  v_slug   text;
  v_home   uuid;
  v_bal    int;
begin
  select * into v_part from public.campaign_participants
    where campaign_id = p_campaign and creator_id = p_creator for update;
  if v_part.id is null then return; end if;
  if v_part.bonus_granted_at is not null then return; end if;            -- primary idempotency guard

  select workspace_id, completion_bonus_points, completion_bonus_xp, status, title, slug
    into v_ws, v_points, v_xp, v_status, v_title, v_slug
    from public.campaigns where id = p_campaign for share;
  if v_status = 'settled' then return; end if;
  if v_part.workspace_id <> v_ws then raise exception 'workspace_mismatch'; end if;

  -- Resolve the creator's HOME workspace (where balances live) — NOT the campaign workspace.
  select workspace_id into v_home from public.creators where id = p_creator;
  if v_home is null then raise exception 'creator % not found', p_creator; end if;

  if coalesce(v_points, 0) > 0 then
    insert into public.point_balances (creator_id, workspace_id, balance)
      values (p_creator, v_home, 0) on conflict (creator_id, workspace_id) do nothing;
    select balance into v_bal from public.point_balances
      where creator_id = p_creator and workspace_id = v_home for update;
    -- Ledger insert FIRST: a duplicate (already paid) aborts here, before we touch the balance.
    begin
      insert into public.point_transactions
        (creator_id, workspace_id, type, delta, balance_after, source_ref, description)
        values (p_creator, v_home, 'bonus', v_points, v_bal + v_points,
                'campaign_bonus:' || p_campaign || ':' || p_creator, '挑戰完成獎賞');
    exception when unique_violation then
      return;   -- DB backstop; primary guard is bonus_granted_at under for update
    end;
    update public.point_balances set balance = balance + v_points, updated_at = now()
      where creator_id = p_creator and workspace_id = v_home;
  end if;

  if coalesce(v_xp, 0) > 0 then
    update public.creators set xp = xp + v_xp where id = p_creator;     -- 0008 trigger recomputes level
  end if;

  update public.campaign_participants set bonus_granted_at = now() where id = v_part.id;

  -- Notification is best-effort ONLY — never roll back the bonus.
  begin
    insert into public.notifications (user_id, workspace_id, type, entity_type, entity_id, data)
      values (p_creator, v_ws, 'campaign_goal_reached', 'campaign', p_campaign,
              jsonb_build_object('campaign_title', coalesce(v_title, ''),
                                 'campaign_slug',  coalesce(v_slug, ''),
                                 'points', coalesce(v_points, 0),
                                 'xp',     coalesce(v_xp, 0)));
  exception when others then
    raise warning 'campaign_goal_reached notification failed for campaign % creator %', p_campaign, p_creator;
  end;
end;
$function$

CREATE OR REPLACE FUNCTION public.join_mission(p_mission uuid)
 RETURNS mission_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator uuid := auth.uid();
  v_ws uuid;
  v_level text;
  m record;
  v_rows int;
  v_sub public.mission_submissions;
begin
  if v_creator is null then raise exception 'not_authenticated'; end if;

  select workspace_id, level into v_ws, v_level
    from public.creators where id = v_creator;
  if v_ws is null then raise exception 'not_found'; end if;

  select id, workspace_id, status, access_type, deadline, required_level, quota, filled
    into m from public.missions where id = p_mission;
  if m.id is null or m.workspace_id <> v_ws then raise exception 'not_found'; end if;
  if m.status <> 'active' then raise exception 'closed'; end if;
  if m.access_type <> 'open' then raise exception 'not_open'; end if;
  if m.deadline is not null and m.deadline < current_date then raise exception 'closed'; end if;

  -- Effective-level gate. L2+ missions need both XP and a verified handle;
  -- the codes are decomposed so the message is honest (earn XP vs verify).
  -- level_ordinal is 1-indexed (L0=1, L1=2, L2=3...) — compare against
  -- level_ordinal('L2'), NOT a bare 2, so the verification gate applies to L2+
  -- only and L0/L1 missions stay XP-only.
  if public.level_ordinal(m.required_level) >= public.level_ordinal('L2') then
    if public.level_ordinal(v_level) < public.level_ordinal(m.required_level) then
      raise exception 'level_locked';
    elsif not exists (
      select 1 from public.creator_social_accounts
      where creator_id = v_creator and owner_verified
    ) then
      raise exception 'verification_required';
    end if;
  elsif public.level_ordinal(v_level) < public.level_ordinal(m.required_level) then
    raise exception 'level_locked';
  end if;

  if exists (select 1 from public.mission_submissions
             where mission_id = p_mission and creator_id = v_creator)
    then raise exception 'already_joined'; end if;

  update public.missions set filled = filled + 1
    where id = p_mission and filled < quota;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then raise exception 'mission_full'; end if;

  begin
    insert into public.mission_submissions
      (mission_id, creator_id, workspace_id, status, xp_awarded)
      values (p_mission, v_creator, v_ws, 'joined', 10)
      returning * into v_sub;
  exception when unique_violation then
    raise exception 'already_joined';
  end;
  update public.creators set xp = xp + 10 where id = v_creator;
  return v_sub;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_level_up()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.level is distinct from old.level and new.xp > old.xp then
    begin
      insert into public.notifications (user_id, workspace_id, type, entity_type, entity_id, data)
        values (new.id, new.workspace_id, 'level_up', 'creator', new.id,
                jsonb_build_object('level', new.level));
    exception when others then null;
    end;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_redemption()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text;
begin
  if new.status = 'fulfilled' then
    begin
      select name into v_name from public.redemption_gifts where id = new.gift_id;
      insert into public.notifications (user_id, workspace_id, type, entity_type, entity_id, data)
        values (new.creator_id, new.workspace_id, 'redemption_ready', 'redemption', new.id,
                jsonb_build_object('gift_name', coalesce(v_name, '')));
    exception when others then null;
    end;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_on_submission_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type text;
  v_mission record;
  v_data jsonb;
begin
  if    old.status = 'applied' and new.status = 'joined'   then v_type := 'application_accepted';
  elsif old.status = 'applied' and new.status = 'declined' then v_type := 'application_declined';
  elsif old.status in ('submitted','under_review') and new.status = 'approved' then v_type := 'submission_approved';
  elsif old.status in ('submitted','under_review') and new.status = 'rejected' then v_type := 'submission_rejected';
  else return new;  -- not a notable transition
  end if;

  begin
    select title, slug into v_mission from public.missions where id = new.mission_id;
    v_data := jsonb_build_object('mission_title', coalesce(v_mission.title, ''),
                                 'mission_slug',  coalesce(v_mission.slug, ''));
    if v_type = 'submission_approved' then
      v_data := v_data || jsonb_build_object('points', new.points_awarded - old.points_awarded,
                                             'xp',     new.xp_awarded - old.xp_awarded);
    elsif v_type = 'submission_rejected' then
      v_data := v_data || jsonb_build_object('reason', coalesce(new.reviewer_notes, ''));
    elsif v_type = 'application_declined' then
      v_data := v_data || jsonb_build_object('notes', coalesce(new.reviewer_notes, ''));
    end if;

    insert into public.notifications (user_id, workspace_id, type, entity_type, entity_id, data)
      values (new.creator_id, new.workspace_id, v_type, 'mission_submission', new.id, v_data);
  exception when others then
    null;  -- notifications are best-effort; NEVER roll back the earn loop
  end;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_gift(p_gift uuid)
 RETURNS redemptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator uuid := auth.uid();
  v_ws uuid;
  g record;
  v_code_id uuid;
  v_code text;
  v_bal int;
  v_red public.redemptions;
begin
  if v_creator is null then raise exception 'not_authenticated'; end if;

  select workspace_id into v_ws from public.creators where id = v_creator;
  if v_ws is null then raise exception 'not_found'; end if;

  -- Lock the gift row to serialise concurrent redeems of the same gift.
  select id, workspace_id, status, points_cost, stock_remaining, valid_from, valid_to, name
    into g from public.redemption_gifts where id = p_gift for update;
  if g.id is null or g.workspace_id <> v_ws then raise exception 'not_found'; end if;
  if g.status <> 'available' then raise exception 'closed'; end if;
  if g.valid_from is not null and g.valid_from > current_date then raise exception 'closed'; end if;
  if g.valid_to   is not null and g.valid_to   < current_date then raise exception 'closed'; end if;
  if g.stock_remaining <= 0 then raise exception 'out_of_stock'; end if;

  select balance into v_bal from public.point_balances
    where creator_id = v_creator and workspace_id = v_ws;
  if v_bal is null or v_bal < g.points_cost then raise exception 'insufficient_points'; end if;

  -- Atomic claim of one available code from the pool.
  update public.redemption_codes set status = 'issued', issued_to = v_creator, issued_at = now()
    where id = (
      select id from public.redemption_codes
      where gift_id = p_gift and status = 'available'
      limit 1 for update skip locked
    )
    returning id, code into v_code_id, v_code;
  if v_code_id is null then raise exception 'out_of_stock'; end if;

  -- Deduct points atomically. The `balance >= points_cost` guard makes this race-safe:
  -- two concurrent redeems of DIFFERENT gifts by the same creator can both pass the
  -- read-check above, but only one can satisfy this predicate at UPDATE time. A null
  -- return means the balance was drained in between → insufficient_points (the whole
  -- tx, including the code claim above, rolls back).
  update public.point_balances set balance = balance - g.points_cost, updated_at = now()
    where creator_id = v_creator and workspace_id = v_ws and balance >= g.points_cost
    returning balance into v_bal;
  if v_bal is null then raise exception 'insufficient_points'; end if;
  insert into public.point_transactions
    (creator_id, workspace_id, type, delta, balance_after, source_ref, description)
    values (v_creator, v_ws, 'redeem', -g.points_cost, v_bal,
            'redemption:' || p_gift, g.name);

  -- Decrement stock + record the redemption.
  update public.redemption_gifts set stock_remaining = stock_remaining - 1 where id = p_gift;
  insert into public.redemptions
    (creator_id, workspace_id, gift_id, code_id, code, points_spent, status)
    values (v_creator, v_ws, p_gift, v_code_id, v_code, g.points_cost, 'fulfilled')
    returning * into v_red;
  return v_red;
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_submission(p_submission uuid, p_notes text)
 RETURNS mission_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sub public.mission_submissions;
begin
  select * into v_sub from public.mission_submissions where id = p_submission for update;
  if v_sub.id is null then raise exception 'not_found'; end if;
  if v_sub.status = 'rejected' then return v_sub; end if;                         -- idempotent
  if v_sub.status not in ('submitted','under_review') then raise exception 'wrong_state'; end if;

  update public.mission_submissions set
    status = 'rejected', reviewed_at = now(), reviewer_notes = p_notes
    where id = p_submission
    returning * into v_sub;
  return v_sub;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_level_from_xp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.level := public.level_for_xp(new.xp);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_campaign(p_campaign uuid)
 RETURNS campaigns
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_c        public.campaigns;
  v_tier     jsonb;
  v_prev_to  int := 0;
  v_row      record;
  v_home     uuid;
  v_pbal     int;
  v_ebal     numeric;
  v_bgt_bal  numeric;
  v_bgt_enf  boolean;
  v_cash     numeric;
  v_points   int;
  v_xp       int;
  v_ref      text;
begin
  select * into v_c from public.campaigns where id = p_campaign for update;
  if v_c.id is null then raise exception 'not_found'; end if;
  if v_c.settled_at is not null then return v_c; end if;        -- idempotent: already settled
  if v_c.status <> 'closed' then raise exception 'wrong_state'; end if;

  -- Re-validate prize_tiers in-RPC: ascending, non-overlapping, non-negative.
  for v_tier in select * from jsonb_array_elements(v_c.prize_tiers) loop
    if (v_tier->>'rank_from')::int < 1
       or (v_tier->>'rank_to')::int < (v_tier->>'rank_from')::int
       or (v_tier->>'rank_from')::int <= v_prev_to
       or coalesce((v_tier->>'cash')::numeric, 0)  < 0
       or coalesce((v_tier->>'points')::int, 0)    < 0
       or coalesce((v_tier->>'xp')::int, 0)        < 0
    then raise exception 'invalid_prize_tiers'; end if;
    v_prev_to := (v_tier->>'rank_to')::int;
  end loop;

  -- Rank via the shared ranker; stamp prize_rank (defensively upserting any missing row).
  for v_row in select * from public.rank_campaign(p_campaign) loop
    insert into public.campaign_participants (campaign_id, creator_id, workspace_id, approved_count)
      values (p_campaign, v_row.creator_id, v_c.workspace_id, v_row.approved)
      on conflict (campaign_id, creator_id) do nothing;
    update public.campaign_participants set prize_rank = v_row.rank
      where campaign_id = p_campaign and creator_id = v_row.creator_id;
  end loop;

  -- Pay each tier. A creator wins at most one rank → one campaign_prize: ref per (campaign,creator).
  for v_tier in select * from jsonb_array_elements(v_c.prize_tiers) loop
    v_cash   := coalesce((v_tier->>'cash')::numeric, 0);
    v_points := coalesce((v_tier->>'points')::int, 0);
    v_xp     := coalesce((v_tier->>'xp')::int, 0);
    for v_row in
      select cp.id as part_id, cp.creator_id, cp.prize_rank
        from public.campaign_participants cp
       where cp.campaign_id = p_campaign
         and cp.prize_rank between (v_tier->>'rank_from')::int and (v_tier->>'rank_to')::int
         and cp.prize_granted_at is null
    loop
      v_ref := 'campaign_prize:' || p_campaign || ':' || v_row.creator_id;
      begin   -- per-winner savepoint
        select workspace_id into v_home from public.creators where id = v_row.creator_id;

        -- CASH: debit the CAMPAIGN workspace budget (hard cap); credit the HOME workspace earnings.
        if v_cash > 0 then
          select balance, enforced into v_bgt_bal, v_bgt_enf
            from public.workspace_budgets where workspace_id = v_c.workspace_id for update;
          if coalesce(v_bgt_enf, false) and coalesce(v_bgt_bal, 0) < v_cash then
            raise exception 'insufficient_budget';   -- NOT caught here → rolls back the whole settle
          end if;
          if v_bgt_bal is not null then
            update public.workspace_budgets set balance = balance - v_cash, updated_at = now()
              where workspace_id = v_c.workspace_id returning balance into v_bgt_bal;
            insert into public.workspace_budget_transactions
              (workspace_id, type, delta, balance_after, source_ref, description)
              values (v_c.workspace_id, 'debit', -v_cash, v_bgt_bal, v_ref, v_c.title);
          end if;
          insert into public.earnings_balances (creator_id, workspace_id, available)
            values (v_row.creator_id, v_home, 0) on conflict (creator_id, workspace_id) do nothing;
          select available into v_ebal from public.earnings_balances
            where creator_id = v_row.creator_id and workspace_id = v_home for update;
          insert into public.earnings_transactions
            (creator_id, workspace_id, type, amount, balance_after, source_ref, description)
            values (v_row.creator_id, v_home, 'earn', v_cash, v_ebal + v_cash, v_ref, v_c.title);
          update public.earnings_balances set available = available + v_cash, updated_at = now()
            where creator_id = v_row.creator_id and workspace_id = v_home;
        end if;

        -- POINTS: HOME workspace.
        if v_points > 0 then
          insert into public.point_balances (creator_id, workspace_id, balance)
            values (v_row.creator_id, v_home, 0) on conflict (creator_id, workspace_id) do nothing;
          select balance into v_pbal from public.point_balances
            where creator_id = v_row.creator_id and workspace_id = v_home for update;
          insert into public.point_transactions
            (creator_id, workspace_id, type, delta, balance_after, source_ref, description)
            values (v_row.creator_id, v_home, 'bonus', v_points, v_pbal + v_points, v_ref, v_c.title);
          update public.point_balances set balance = balance + v_points, updated_at = now()
            where creator_id = v_row.creator_id and workspace_id = v_home;
        end if;

        -- XP.
        if v_xp > 0 then
          update public.creators set xp = xp + v_xp where id = v_row.creator_id;
        end if;

        update public.campaign_participants set prize_granted_at = now() where id = v_row.part_id;

        begin   -- best-effort notification
          insert into public.notifications (user_id, workspace_id, type, entity_type, entity_id, data)
            values (v_row.creator_id, v_c.workspace_id, 'campaign_prize_awarded', 'campaign', p_campaign,
                    jsonb_build_object('campaign_title', coalesce(v_c.title, ''),
                                       'campaign_slug',  coalesce(v_c.slug, ''),
                                       'rank',   v_row.prize_rank,
                                       'cash',   v_cash,
                                       'points', v_points,
                                       'xp',     v_xp));
        exception when others then
          raise warning 'campaign_prize_awarded notification failed for campaign % creator %', p_campaign, v_row.creator_id;
        end;

      exception
        when unique_violation then null;   -- already paid → skip this winner (DB backstop)
      end;
    end loop;
  end loop;

  update public.campaigns set status = 'settled', settled_at = now(), updated_at = now()
    where id = p_campaign returning * into v_c;
  return v_c;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_mission(p_mission uuid, p_urls text[], p_data jsonb)
 RETURNS mission_submissions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator uuid := auth.uid();
  v_sub public.mission_submissions;
begin
  if v_creator is null then raise exception 'not_authenticated'; end if;
  if p_urls is null or array_length(p_urls, 1) is null then raise exception 'empty_urls'; end if;

  select * into v_sub from public.mission_submissions
    where mission_id = p_mission and creator_id = v_creator for update;
  if v_sub.id is null then raise exception 'wrong_state'; end if;
  if v_sub.status <> 'joined' then raise exception 'wrong_state'; end if;

  update public.mission_submissions set
    status = 'submitted',
    content_urls = p_urls,
    submission_data = coalesce(p_data, '{}'::jsonb),
    submitted_at = now(),
    review_deadline = now() + interval '48 hours',   -- fixed SLA; per-mission column lands with the S9 cron
    xp_awarded = xp_awarded + 25
    where id = v_sub.id
    returning * into v_sub;
  update public.creators set xp = xp + 25 where id = v_creator;
  return v_sub;
end;
$function$
